export const SampleResultContent = ({ type = "nin" }) => {
  const { t } = useLocale();
  const sample = sampleData[type] || sampleData.nin;
  const Icon = sample.icon;

  return (
    <>
      <ResultCard>
        {sample.banner && sample.image && (
          <PhotoBanner>
            <img src={sample.image} alt="Sample vehicle" />
          </PhotoBanner>
        )}
        <Top>
          {!sample.banner && (
            <Avatar>
              {sample.image ? (
                <img src={sample.image} alt="Sample person" />
              ) : (
                Icon && <Icon />
              )}
            </Avatar>
          )}
          <ResultGrid>
            {sample.fields.map(([label, value, status]) => (
              <ResultField key={label}>
                <ResultLabel>{t(labelToKey[label] || label)}</ResultLabel>
                {status === "verified" ? (
                  <VerifiedValue>
                    {value} <FaCheckCircle />
                  </VerifiedValue>
                ) : (
                  <ResultValue>{value}</ResultValue>
                )}
              </ResultField>
            ))}
          </ResultGrid>
        </Top>
        {sample.stakeholders && (
          <StakeholderSection>
            <StakeholderSectionTitle>
              {t("sample.stakeholders")}
            </StakeholderSectionTitle>
            <StakeholderTable>
              <StakeholderRow $header>
                <StakeholderCell $header>
                  {t("sample.stakeholderName")}
                </StakeholderCell>
                <StakeholderCell $header>
                  {t("sample.stakeholderRole")}
                </StakeholderCell>
                <StakeholderCell $header>
                  {t("sample.stakeholderNationality")}
                </StakeholderCell>
              </StakeholderRow>
              {sample.stakeholders.map((s, i) => (
                <StakeholderRow key={i}>
                  <StakeholderCell>{s.name}</StakeholderCell>
                  <StakeholderCell>{s.role}</StakeholderCell>
                  <StakeholderCell>{s.nationality}</StakeholderCell>
                </StakeholderRow>
              ))}
            </StakeholderTable>
          </StakeholderSection>
        )}
      </ResultCard>

      <Disclaimer>
        <FaInfoCircle />
        {t("sample.disclaimer")}
      </Disclaimer>
    </>
  );
};

const SampleResultPopup = ({ isOpen, onClose, type = "nin" }) => {
  const { t } = useLocale();
  const sample = sampleData[type] || sampleData.nin;

  useEffect(() => {
    if (!isOpen) return undefined;

    const handleKeyDown = (event) => {
      if (event.key === "Escape") {
        onClose();
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    document.body.style.overflow = "hidden";

    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      document.body.style.overflow = "";
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <Overlay onClick={onClose} role="presentation">
      <Dialog
        $isVehicle={type === "vehicle"}
        role="dialog"
        aria-modal="true"
        aria-labelledby="sample-result-title"
        onClick={(event) => event.stopPropagation()}
      >
        <Header $isVehicle={type === "vehicle"}>
          <div>
            <TitleRow>
              <Title id="sample-result-title">{t("sample.title")}</Title>
              <Badge>{t("sample.badge")}</Badge>
            </TitleRow>
            <Subtitle>
              {type === "vehicle"
                ? "See what your VIN verification report can reveal before you buy."
                : t(subtypeToKey[type] || "sample.ninSubtitle")}
            </Subtitle>
          </div>

          <HeaderRight>
            {type === "vehicle" && (
              <HeaderTrustBadge>
                <HeaderTrustIcon>
                  <FaShieldAlt />
                </HeaderTrustIcon>
                <HeaderTrustText>
                  <strong>Trusted data. Safer purchases.</strong>
                  <span>Get the full report in seconds.</span>
                </HeaderTrustText>
              </HeaderTrustBadge>
            )}
            <CloseButton type="button" onClick={onClose} aria-label="Close">
              <FaTimes />
            </CloseButton>
          </HeaderRight>
        </Header>

        {type === "vehicle" ? (
          <VehicleSampleResult onClose={onClose} />
        ) : (
          <SampleResultContent type={type} />
        )}
      </Dialog>
    </Overlay>
  );
};

